package com.example.agendapersonal.ui;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.net.Uri;import android.widget.*;import com.example.agendapersonal.R;import com.example.agendapersonal.avisos.ProgramadorAvisos;
public class NotificacionesActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private TextView estado;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_notificaciones);estado=findViewById(R.id.estadoAvisos);findViewById(R.id.permisoAvisos).setOnClickListener(v->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},9);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));});findViewById(R.id.permisoExacto).setOnClickListener(v->{if(Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));});findViewById(R.id.permisoFlotante).setOnClickListener(v->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));Switch f=findViewById(R.id.activarFlotante);f.setChecked(getSharedPreferences("agenda_avisos",MODE_PRIVATE).getBoolean("flotante",false));f.setOnCheckedChangeListener((v,x)->{getSharedPreferences("agenda_avisos",MODE_PRIVATE).edit().putBoolean("flotante",x).apply();ProgramadorAvisos.actualizar(this);});findViewById(R.id.volverAvisos).setOnClickListener(v->finish());}
 @Override protected void onResume(){super.onResume();ProgramadorAvisos.canales(this);estado.setText("Notificaciones: "+(ProgramadorAvisos.permiso(this)?"habilitadas":"pendientes de permiso")+"\nHorario preciso: "+(Build.VERSION.SDK_INT<31||getSystemService(AlarmManager.class).canScheduleExactAlarms()?"habilitado":"Android puede demorar los avisos")+"\nVentana flotante: "+(Settings.canDrawOverlays(this)?"permiso concedido":"pendiente de permiso")+"\n\nLas alarmas de tareas usan el inicio; las de eventos, su fecha. Sin hora, se toma el inicio del día. Las actividades finalizadas, canceladas o postergadas no generan avisos.");ProgramadorAvisos.actualizar(this);}
}
